#define wmain batch_main
#include "batch_cut_units.cpp"
#undef wmain
#include <gp_Ax1.hxx>

int wmain(int argc,wchar_t** argv){try{
    if(argc!=5)throw std::runtime_error("usage: logical_boundary_tests source.step controls.txt face-id output-folder");
    fs::path input=argv[1],out=argv[4];fs::create_directories(out);int target=std::stoi(argv[3]);
    std::ifstream ctl(argv[2]);int count;ctl>>count;FaceControl control;
    for(int i=0;i<count;++i){int id,complete,mask,n;ctl>>id>>complete>>mask>>n;FaceControl item;item.complete=complete;item.mask=mask;for(int j=0;j<n;++j){LogicalGroup g;int closed,straight,k;ctl>>g.wire>>g.role>>closed>>straight>>k;g.closed=closed;g.straight=straight;for(int q=0;q<k;++q){int e,r;ctl>>e>>r;g.edges.push_back({e,r});}item.groups.push_back(g);}if(id==target)control=item;}
    STEPControl_Reader reader;if(reader.ReadFile(utf8(input).c_str())!=IFSelect_RetDone)throw std::runtime_error("source-read-failed");reader.TransferRoots();TopTools_IndexedMapOfShape faces,edges;TopExp::MapShapes(reader.OneShape(),TopAbs_FACE,faces);TopExp::MapShapes(reader.OneShape(),TopAbs_EDGE,edges);auto original=TopoDS::Face(faces(target));
    auto check=[&](const TopoDS_Face& face,const char* label){auto result=solve(face,control,edges,.01);if(result.pieces.size()!=1||result.pieces[0].method!="logical-skin-loop-planar"||result.pieces[0].axis!=-1||!result.pieces[0].lines.empty())throw std::runtime_error(label);if(std::abs(area(result.pieces[0].face)-area(face))>1e-7)throw std::runtime_error("area-changed");};
    check(original,"original-not-one-boundary-unit");
    auto plane=BRepAdaptor_Surface(original).Plane();int rotations=0;
    for(double angle:{.173,std::acos(-1.)/4,1.234,std::acos(-1.)/2}){auto axes=plane.Position();axes.Rotate(gp_Ax1(axes.Location(),axes.Direction()),angle);auto face=BRepBuilderAPI_MakeFace(gp_Pln(axes),BRepTools::OuterWire(original),true).Face();if(!BRepCheck_Analyzer(face).IsValid()||differenceArea(original,face)>1e-7||differenceArea(face,original)>1e-7)throw std::runtime_error("reparameterized-region-changed");check(face,"uv-rotation-changed-unit");++rotations;}
    gp_Trsf placement;placement.SetRotation(gp_Ax1(gp_Pnt(0,0,0),gp_Dir(1,2,3)),.61);auto moved=TopoDS::Face(BRepBuilderAPI_Transform(original,placement,true).Shape());check(moved,"world-rotation-changed-unit");
    Piece unused;auto changed=control;changed.groups.front().role=2;if(logicalSkinLoop(original,changed,unused))throw std::runtime_error("side-boundary-incorrectly-ignored");changed=control;changed.groups.front().role=4;if(logicalSkinLoop(original,changed,unused))throw std::runtime_error("internal-boundary-incorrectly-ignored");changed=control;changed.complete=false;if(logicalSkinLoop(original,changed,unused))throw std::runtime_error("unresolved-boundary-incorrectly-accepted");
    GProp_GProps centroid;BRepGProp::SurfaceProperties(original,centroid);auto hole=BRepBuilderAPI_MakeWire(BRepBuilderAPI_MakeEdge(gp_Circ(gp_Ax2(centroid.CentreOfMass(),plane.Axis().Direction()),1))).Wire();hole.Reverse();BRepBuilderAPI_MakeFace perforated(original);perforated.Add(hole);if(!BRepCheck_Analyzer(perforated.Face()).IsValid())throw std::runtime_error("invalid-hole-test-fixture");if(logicalSkinLoop(perforated.Face(),control,unused))throw std::runtime_error("hole-incorrectly-ignored");
    auto path=out/"source-face.brep";BRepTools::Write(original,utf8(path).c_str());writeMesh(original,out/"source-face.mesh.json");auto result=solve(original,control,edges,.01);auto unit=out/"checked-unit.brep";BRepTools::Write(result.pieces[0].face,utf8(unit).c_str());TopoDS_Shape round;BRep_Builder builder;if(!BRepTools::Read(round,utf8(unit).c_str(),builder)||!BRepCheck_Analyzer(round).IsValid())throw std::runtime_error("unit-round-trip-invalid");double missing=differenceArea(original,round),extra=differenceArea(round,original);if(missing>1e-7||extra>1e-7)throw std::runtime_error("unit-coverage-changed");
    std::ofstream json(out/"logical-validation.json");json<<std::setprecision(15)<<"{\"sourceFaceCount\":"<<faces.Extent()<<",\"faceId\":"<<target<<",\"unitCount\":1,\"newSplitCount\":0,\"logicalGroups\":"<<control.groups.size()<<",\"areaMm2\":"<<area(original)<<",\"missingAreaMm2\":"<<missing<<",\"extraAreaMm2\":"<<extra<<",\"uvRotationsPassed\":"<<rotations<<",\"worldRotationPassed\":true,\"sideInternalUnknownAndHoleRejected\":true,\"sourceAndReadbackValid\":true}";
    std::cout<<"logical boundary tests passed; one unit, zero added seams, UV and world rotation invariant\n";return 0;
}catch(const Standard_Failure& e){std::cerr<<e.GetMessageString();return 1;}catch(const std::exception& e){std::cerr<<e.what();return 1;}}
